INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5847805, 847756, 103142, '<td valign="top">ok, I hope you''ve posted the story behind this shot, because I''d really like to know!</td>', 'ok, I hope you''ve posted the story behind this shot, because I''d really like to know!', '2010-02-01 15:32:38.000000', NULL, 1),
(5847808, 850966, 103142, '<td valign="top">Like your other shot better. This one''s nice, but since their heads are looking away, it makes them look kind of headless.</td>', 'Like your other shot better. This one''s nice, but since their heads are looking away, it makes them look kind of headless.', '2010-02-01 15:33:47.000000', NULL, 1),
(5847815, 851008, 103142, '<td valign="top">That looks like my cat, Tucker! <a href="//www.dpchallenge.com/image.php?IMAGE_ID=851235" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_851235.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_851235.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/100000-104999/103142/120/Copyrighted_Image_Reuse_Prohibited_851235.jpg"/></a> <br/> <br/>Fun shot, I like the tight fit.</td>', 'That looks like my cat, Tucker!   Fun shot, I like the tight fit.', '2010-02-01 15:36:25.000000', NULL, 1),
(5847819, 851242, 103142, '<td valign="top">aww! And now they announce a chair challenge!<br/> <br/>Fun shot, very nicely done.</td>', 'aww! And now they announce a chair challenge! Fun shot, very nicely done.', '2010-02-01 15:37:03.000000', NULL, 1),
