(5852001, 846259, 42495, '<td valign="top">That''s a face to be studied, she''s certainly seen a lot as evidence in her face and eyes.  The blanket adds so much, it''s worn nearly as much as she is.</td>', 'That''s a face to be studied, she''s certainly seen a lot as evidence in her face and eyes.  The blanket adds so much, it''s worn nearly as much as she is.', '2010-02-03 22:55:19.000000', NULL, 1),
(5852007, 849188, 42495, '<td valign="top">I like the colors and detail, but a bit overdone IMO on the HDR.</td>', 'I like the colors and detail, but a bit overdone IMO on the HDR.', '2010-02-03 23:03:02.000000', NULL, 1),
(5852016, 849499, 42495, '<td valign="top">Excellent detail I like that one little person there.  If that backpack (or whatever) were yellow/orange instead of green this would be awesome for a Waldo challenge.</td>', 'Excellent detail I like that one little person there.  If that backpack (or whatever) were yellow/orange instead of green this would be awesome for a Waldo challenge.', '2010-02-03 23:11:44.000000', NULL, 1),
(5852018, 849464, 42495, '<td valign="top">I like the detail and colors, but not fond of the tilt.</td>', 'I like the detail and colors, but not fond of the tilt.', '2010-02-03 23:13:50.000000', NULL, 1),
(5852026, 847904, 42495, '<td valign="top">Lovely high key image, love the bokeh.</td>', 'Lovely high key image, love the bokeh.', '2010-02-03 23:18:29.000000', NULL, 1),
