(5852103, 848301, 30982, '<td valign="top">Wonderful sense of distance and scale.  Lovely variety of trees.</td>', 'Wonderful sense of distance and scale.  Lovely variety of trees.', '2010-02-04 00:58:36.000000', NULL, 1),
(5852105, 850730, 30982, '<td valign="top">Wonderfully seen!  I especially like the single eye on the left.  Great DOF here.</td>', 'Wonderfully seen!  I especially like the single eye on the left.  Great DOF here.', '2010-02-04 01:00:14.000000', NULL, 1),
(5852106, 847743, 30982, '<td valign="top">A bizarre but strangely beautiful place, Joshua Tree... Lovely shot of the place!</td>', 'A bizarre but strangely beautiful place, Joshua Tree... Lovely shot of the place!', '2010-02-04 01:00:43.000000', NULL, 1),
(5852121, 851241, 30982, '<td valign="top">What wonderful light - very crisp, very clean.  I can feel the cold, smell that crisp air.  Well captured.</td>', 'What wonderful light - very crisp, very clean.  I can feel the cold, smell that crisp air.  Well captured.', '2010-02-04 01:18:25.000000', NULL, 1),
(5852122, 845424, 30982, '<td valign="top">Normally I am not a big fan of crying chidlren pictures, but this one is somehow both sweet and almost funny (though I suspect she doesn''t think so!)</td>', 'Normally I am not a big fan of crying chidlren pictures, but this one is somehow both sweet and almost funny (though I suspect she doesn''t think so!)', '2010-02-04 01:19:01.000000', NULL, 1),
(5852123, 846581, 30982, '<td valign="top">Very nicely captured!  He really looks like he''s having fun, and I have to admit I''ve not seen the underside of a zebra before - interesting how the stripes come together!</td>', 'Very nicely captured!  He really looks like he''s having fun, and I have to admit I''ve not seen the underside of a zebra before - interesting how the stripes come together!', '2010-02-04 01:19:55.000000', NULL, 1),
(5852125, 850820, 30982, '<td valign="top">Stark and striking.  Excellent processing to create the mood here.</td>', 'Stark and striking.  Excellent processing to create the mood here.', '2010-02-04 01:20:20.000000', NULL, 1),
(5852127, 850907, 30982, '<td valign="top">Beuatifully captured and presented.  Love the warmth of the light.  Excellent detail as well.</td>', 'Beuatifully captured and presented.  Love the warmth of the light.  Excellent detail as well.', '2010-02-04 01:21:13.000000', NULL, 1),
(5852128, 851279, 30982, '<td valign="top">Striking and compelling.</td>', 'Striking and compelling.', '2010-02-04 01:21:27.000000', NULL, 1),
(5852130, 850941, 30982, '<td valign="top">This makes me smile!  Love how the coloring matches the background - a fine "action" portrait!</td>', 'This makes me smile!  Love how the coloring matches the background - a fine "action" portrait!', '2010-02-04 01:22:10.000000', NULL, 1),
(5852132, 851171, 30982, '<td valign="top">Sweet as can be!</td>', 'Sweet as can be!', '2010-02-04 01:22:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5852133, 849489, 30982, '<td valign="top">Striking detail!  Love the currents in the water, and what a wonderful day you had to shoot this!</td>', 'Striking detail!  Love the currents in the water, and what a wonderful day you had to shoot this!', '2010-02-04 01:22:52.000000', NULL, 1),
(5852134, 850933, 30982, '<td valign="top">Suave and debonair!</td>', 'Suave and debonair!', '2010-02-04 01:23:06.000000', NULL, 1),
(5852135, 850328, 30982, '<td valign="top">Wonderful composition to show off the sky and the water.  Glad you had a pedestrian in there as well.</td>', 'Wonderful composition to show off the sky and the water.  Glad you had a pedestrian in there as well.', '2010-02-04 01:23:42.000000', NULL, 1),
(5852136, 850407, 30982, '<td valign="top">How can you miss with a smile like that??  Sweet!</td>', 'How can you miss with a smile like that??  Sweet!', '2010-02-04 01:23:56.000000', NULL, 1),
(5852138, 850112, 30982, '<td valign="top">An ominous, sterile kind of view.  And very nicely presented.  I like the light reflecting off the windows of the center building.</td>', 'An ominous, sterile kind of view.  And very nicely presented.  I like the light reflecting off the windows of the center building.', '2010-02-04 01:24:34.000000', NULL, 1),
(5852140, 850149, 30982, '<td valign="top">Definitely in the running for best title, and darn fine shot as well.</td>', 'Definitely in the running for best title, and darn fine shot as well.', '2010-02-04 01:25:21.000000', NULL, 1),
(5852141, 851033, 30982, '<td valign="top">Love the footsteps on the stairs!  A very good B&amp;W.</td>', 'Love the footsteps on the stairs!  A very good B&W.', '2010-02-04 01:25:39.000000', NULL, 1),
(5852142, 850991, 30982, '<td valign="top">Hmmm - this looks like a palace at Victory complex in Iraq.  Gorgeous sky and this is an excellent angle if it''s the place I think it is.</td>', 'Hmmm - this looks like a palace at Victory complex in Iraq.  Gorgeous sky and this is an excellent angle if it''s the place I think it is.', '2010-02-04 01:26:05.000000', NULL, 1),
(5852143, 849183, 30982, '<td valign="top">Great use of deep DOF to have detail throughout, and a very strong, pleasing composition.  Cold, but beautiful!</td>', 'Great use of deep DOF to have detail throughout, and a very strong, pleasing composition.  Cold, but beautiful!', '2010-02-04 01:27:28.000000', NULL, 1),
(5852146, 851125, 30982, '<td valign="top">Entirely too adorable!!  Well photographed, too.</td>', 'Entirely too adorable!!  Well photographed, too.', '2010-02-04 01:28:15.000000', NULL, 1),
(5852147, 849047, 30982, '<td valign="top">How very elegant!  Lovely composition choice.</td>', 'How very elegant!  Lovely composition choice.', '2010-02-04 01:28:33.000000', NULL, 1),
