(5852149, 851170, 30982, '<td valign="top">The golden light here is wonderful on all that ice.</td>', 'The golden light here is wonderful on all that ice.', '2010-02-04 01:29:40.000000', NULL, 1),
(5852150, 850212, 30982, '<td valign="top">Vast, expansive, and beautifully toned.</td>', 'Vast, expansive, and beautifully toned.', '2010-02-04 01:30:13.000000', NULL, 1),
(5852151, 845917, 30982, '<td valign="top">Speed skating contender in the upcoming Olympics, perhaps?  Showing very good form!</td>', 'Speed skating contender in the upcoming Olympics, perhaps?  Showing very good form!', '2010-02-04 01:30:39.000000', NULL, 1),
(5852152, 846683, 30982, '<td valign="top">Gorgeous light.</td>', 'Gorgeous light.', '2010-02-04 01:30:53.000000', NULL, 1),
