(5852621, 847403, 98339, '<td valign="top">this is what I call stark beauty</td>', 'this is what I call stark beauty', '2010-02-04 11:21:03.000000', NULL, 1),
(5852625, 851276, 98339, '<td valign="top">this is very well done...one of the better portraits in the bunch...one thing...not sure if you did this or not...but it appears that you put possibly a gaussian blur on the picture...I personally would have bumped this up if her face had been much clearer which would have involved erasing over her face to remove the filter...now those are alot of assumptions on my part...but I do love the vivid color of her coat and her expression...very well done</td>', 'this is very well done...one of the better portraits in the bunch...one thing...not sure if you did this or not...but it appears that you put possibly a gaussian blur on the picture...I personally would have bumped this up if her face had been much clearer which would have involved erasing over her face to remove the filter...now those are alot of assumptions on my part...but I do love the vivid color of her coat and her expression...very well done', '2010-02-04 11:22:59.000000', NULL, 1),
(5852626, 851320, 98339, '<td valign="top">is this one of those "miniture" lens''?  kind a of a cool shot...love the clarity and how the train and traffic looks sooooo small</td>', 'is this one of those "miniture" lens''?  kind a of a cool shot...love the clarity and how the train and traffic looks sooooo small', '2010-02-04 11:23:42.000000', NULL, 1),
