(5855796, 849953, 76335, '<td valign="top">Why am I such a sucker for cross-processed looking beach shots? Don''t know. Nine for now...</td>', 'Why am I such a sucker for cross-processed looking beach shots? Don''t know. Nine for now...', '2010-02-06 19:50:56.000000', NULL, 1),
(5855800, 850298, 76335, '<td valign="top">The title is kind of cryptic. Are you referring to the mixed lighting? On its own, the composition doesn''t do much for me.</td>', 'The title is kind of cryptic. Are you referring to the mixed lighting? On its own, the composition doesn''t do much for me.', '2010-02-06 19:52:27.000000', NULL, 1),
(5855803, 850946, 76335, '<td valign="top">A beautiful composition but the HDR feels unnatural. A place like this needs its dark nooks and crannies preserved.</td>', 'A beautiful composition but the HDR feels unnatural. A place like this needs its dark nooks and crannies preserved.', '2010-02-06 19:54:34.000000', NULL, 1),
(5855805, 850149, 100831, '<td valign="top">how cute! what a wonderful catch - great, great picture!</td>', 'how cute! what a wonderful catch - great, great picture!', '2010-02-06 19:55:15.000000', NULL, 1),
(5855807, 850168, 76335, '<td valign="top">The saturation is a little over the top...</td>', 'The saturation is a little over the top...', '2010-02-06 19:56:11.000000', NULL, 1),
