INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5858116, 851290, 83313, '<td valign="top">Sorry for not leaving an in-challenge comment on this one, but I had given it an 8, and I prefer to spend more time commenting on the lower votes I give. I really thought this would come in the vicinity of a 6, but I suppose the quirky shots are not for everyone.</td>', 'Sorry for not leaving an in-challenge comment on this one, but I had given it an 8, and I prefer to spend more time commenting on the lower votes I give. I really thought this would come in the vicinity of a 6, but I suppose the quirky shots are not for everyone.', '2010-02-08 00:49:19.000000', NULL, 0),
(5858121, 851011, 30982, '<td valign="top">Expertly done, Mark.  Great work.</td>', 'Expertly done, Mark.  Great work.', '2010-02-08 00:51:23.000000', NULL, 0),
(5858148, 844653, 83313, '<td valign="top">Got a 7 from me, but I''m one of the folks that likes abstract photography. BTW, I am very jealous of your performance in this challenge. The voting breakdown shows a dip in the 5''s, with higher 4''s and 6''s around it. You have achieved a "love it or hate it" entry, which is one of my own goals. Looking at the breakdown some more, this entry also appears to have found it''s share of fans. The way I read the results, this was a far more successful entry than many that averaged higher.</td>', 'Got a 7 from me, but I''m one of the folks that likes abstract photography. BTW, I am very jealous of your performance in this challenge. The voting breakdown shows a dip in the 5''s, with higher 4''s and 6''s around it. You have achieved a "love it or hate it" entry, which is one of my own goals. Looking at the breakdown some more, this entry also appears to have found it''s share of fans. The way I read the results, this was a far more successful entry than many that averaged higher.', '2010-02-08 01:00:43.000000', NULL, 0),
